/*
 * Qt OpenAPI OAuth 2.0 demo - user profile
 *
 * Demo authorization and resource server for the Qt OpenAPI oauth2client
 * example. The routes under /api are generated from oauth2client.yaml with the
 * go-gin-server generator, the OAuth 2.0 endpoints under /oauth are
 * hand-written in go/oauth_server.go.
 *
 * API version: 1.0.0
 * Generated by: OpenAPI Generator (https://openapi-generator.tech)
 */

package main

import (
	"io"
	"log"
	"os"

	"github.com/gin-gonic/gin"

	sw "oauth2server/go"
)

// Keep in sync with the servers and securitySchemes entries of oauth2client.yaml.
const listenAddress = "127.0.0.1:20500"

func main() {
	gin.SetMode(gin.ReleaseMode)

	auth := sw.NewAuthorizationServer()
	routes := sw.ApiHandleFunctions{
		UsersAPI: sw.UsersAPI{Auth: auth},
	}

	router := sw.NewRouter(routes)
	auth.RegisterRoutes(router)

	log.Printf("Demo authorization and resource server listening on http://%s", listenAddress)
	log.Printf("Accepting client_id %q with PKCE (S256) and loopback redirect URIs", sw.ClientID)

	// The example application starts this server as a child process with a
	// pipe on stdin. When the application exits, for whatever reason, the pipe
	// closes and the server shuts down with it instead of lingering.
	go func() {
		_, _ = io.Copy(io.Discard, os.Stdin)
		log.Printf("Standard input closed, shutting down")
		os.Exit(0)
	}()

	log.Fatal(router.Run(listenAddress))
}
